define(['jquery','uiRegistry'],function($,registry){'use strict';var shippingPrefix='checkout.steps.shipping-step.shippingAddress.shipping-address-fieldset.';function fixRegionDropdown(){registry.get(shippingPrefix+'region_id',function(regionComponent){regionComponent.visible(true);if(regionComponent.caption){regionComponent.caption('S\u00e9lectionnez une wilaya');}
registry.get(shippingPrefix+'country_id',function(countryComponent){countryComponent.value.subscribe(function(newCountry){if(newCountry==='DZ'){setTimeout(function(){regionComponent.visible(true);if(regionComponent.caption){regionComponent.caption('S\u00e9lectionnez une wilaya');}},300);}});});});}
function bindWilayaChangeEvent(){$(document).on('change','select[name="region_id"]',function(){var wilayaId=$(this).val(),$countrySelect=$(this).closest('form, fieldset').find('select[name="country_id"]');if((!$countrySelect.length||$countrySelect.val()==='DZ')&&wilayaId){$(this).trigger('wilaya:changed',[wilayaId]);$(document).trigger('wilaya:changed',[wilayaId]);}});}
return function(){registry.async(shippingPrefix+'region_id')(function(){fixRegionDropdown();});$(document).ready(function(){bindWilayaChangeEvent();setTimeout(function(){var $regionDiv=$('div[name="shippingAddress.region_id"]');if($regionDiv.length&&$regionDiv.css('display')==='none'){$regionDiv.show();}},2000);});};});